import {simpleInsights} from './insights-view.mjs';
import {KEY,uid,cents,stock,inventoryValue,orderTotal,insights,load,commit,apply,seed,parseCSV} from './stock-model.mjs';
const $=s=>document.querySelector(s);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,storageError='',page='overview',detail='',filters={},modalType='',modalId='',modalToken='',csvRows=[],importRows=[],toastTimer;
try{state=load(localStorage);}catch(error){storageError=error.message;state=seed();}
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:state.settings.currency}).format(n/100);
const date=at=>new Date(at).toLocaleDateString('en-US',{month:'short',day:'numeric'});
const fullDate=at=>new Date(at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const pname=id=>state.products.find(p=>p.id===id)?.name||'Unknown product';
const lname=id=>state.settings.locations.find(l=>l.id===id)?.name||'Unknown location';
const contactName=(kind,id)=>state[kind].find(c=>c.id===id)?.name||'Unknown contact';
const icons={overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',inventory:'m3 7 9-4 9 4v10l-9 4-9-4zM3 7l9 4 9-4M12 11v10',sales:'M6 3h12v18H6zM9 8h6M9 12h6M9 16h4',purchasing:'M3 5h2l3 11h10l3-8H6M9 21h.01M18 21h.01',customers:'M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2M12 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',suppliers:'M3 21V7l9-4 9 4v14M7 21v-7h10v7M7 9h.01M12 9h.01M17 9h.01',insights:'M4 20V10M10 20V4M16 20v-7M22 20H2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',check:'m5 12 4 4L19 6',box:'m3 7 9-4 9 4v10l-9 4-9-4zM3 7l9 4 9-4M12 11v10',menu:'M4 6h16M4 12h16M4 18h16'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.box}"/></svg>`;
const badge=status=>`<span class="badge ${['Low stock','Partially received'].includes(status)?'amber':['Out of stock','Cancelled'].includes(status)?'red':['Fulfilled','Received'].includes(status)?'green':['Confirmed','Open'].includes(status)?'blue':''}">${e(status)}</span>`;
const stockStatus=(p,locationId)=>{const a=stock(state,p.id,locationId).available;return a===0?'Out of stock':a<=p.reorderPoint?'Low stock':'In stock';};
const btn=(label,action,cls='primary',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const option=(value,label,selected)=>`<option value="${e(value)}" ${String(selected)===String(value)?'selected':''}>${e(label)}</option>`;
const select=(name,label,options,selected='',empty='All')=>`<label class="filter-select"><span class="sr-only">${label}</span><select name="${name}" data-filter="${name}" aria-label="${label}">${empty!==null?option('',empty,selected):''}${options.map(o=>option(o.value??o.id??o,o.label??o.name??o,selected)).join('')}</select></label>`;
const empty=(title,copy)=>`<div class="empty-state">${icon('box')}<h3>${title}</h3><p>${copy}</p></div>`;
const table=(headers,rows)=>`<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">${empty('Nothing here yet','Try a different filter or add your first record.')}</td></tr>`}</tbody></table></div>`;
const head=(eyebrow,title,copy,actions='')=>`<header class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div><div class="heading-actions">${actions}</div></header>`;
function toast(message,error=false){$('#toast').textContent=message;$('#toast').className='toast visible'+(error?' toast-error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').className='toast',4500);}
function productCell(p){return `<a class="product-link" href="#app/inventory/${p.id}"><span class="product-avatar">${e(p.name.split(' ').slice(0,2).map(w=>w[0]).join(''))}</span><span><b>${e(p.name)}</b><small>${e(p.sku)}</small></span></a>`;}
function metric(label,value,note,kind='overview',color=''){return `<article class="metric-card"><div><span>${label}</span><div class="metric-icon ${color}">${icon(kind)}</div></div><strong>${value}</strong><small>${note}</small></article>`;}
function chart(type,preview=false){
  const buckets=Array.from({length:14},(_,i)=>{const at=new Date();at.setDate(at.getDate()-13+i);return {day:at.toISOString().slice(0,10),label:at.toLocaleDateString('en-US',{month:'short',day:'numeric'}),value:0,in:0,out:0};});
  if(type==='sales')for(const order of state.orders.filter(o=>o.status==='Fulfilled')){const b=buckets.find(b=>b.day===order.fulfilledAt.slice(0,10));if(b)b.value+=orderTotal(order);}
  else for(const m of state.movements){const b=buckets.find(b=>b.day===m.at.slice(0,10));if(b){b.in+=Math.max(0,m.delta);b.out+=Math.max(0,-m.delta);}}
  const max=Math.max(1,...buckets.map(b=>type==='sales'?b.value:Math.max(b.in,b.out))),height=135;
  const bars=buckets.map((b,i)=>{const x=42+i*30;const h=height*(type==='sales'?b.value:b.in)/max;const h2=height*b.out/max;return `<g><title>${e(b.label)}: ${type==='sales'?money(b.value):`${b.in} units in, ${b.out} units out`}</title><rect x="${x}" y="${165-h}" width="${type==='sales'?16:9}" height="${h}" rx="3" fill="${type==='sales'?'#2878ef':'#0b9a87'}"/>${type==='movement'?`<rect x="${x+11}" y="${165-h2}" width="9" height="${h2}" rx="3" fill="#2878ef"/>`:''}</g>`;}).join('');
  const total=type==='sales'?buckets.reduce((n,b)=>n+b.value,0):buckets.reduce((n,b)=>n+b.out,0);
  return `<section class="card chart-card"><div class="card-heading"><div><h2>${type==='sales'?'Recent sales':'Stock movement'}</h2><p>${type==='sales'?'Fulfilled orders · last 14 days':'Physical units · last 14 days'}</p></div><span class="subtle-pill">14 days</span></div><div class="chart-total">${type==='sales'?money(total):total+' units out'}<span>${type==='sales'?'Product sales, before tax':'Receipts and stock deductions'}</span></div><svg viewBox="0 0 480 200" role="img" aria-label="${type==='sales'?'Daily fulfilled sales totals':'Daily units received and removed'}"><path d="M35 30H465M35 75H465M35 120H465M35 165H465" stroke="#edf1f5"/>${bars}<text x="35" y="190">${e(buckets[0].label)}</text><text x="210" y="190">${e(buckets[6].label)}</text><text x="420" y="190">${e(buckets[13].label)}</text></svg>${type==='movement'?'<div class="chart-legend"><span><i class="teal"></i>Stock in</span><span><i class="blue"></i>Stock out</span></div>':''}${!preview?`<details class="chart-data"><summary>View daily values</summary>${table(['Date',...(type==='sales'?['Sales']:['Stock in','Stock out'])],buckets.map(b=>`<tr><td>${b.label}</td>${type==='sales'?`<td>${money(b.value)}</td>`:`<td>${b.in}</td><td>${b.out}</td>`}</tr>`))}</details>`:''}</section>`;
}
function overview(preview=false){
  const low=state.products.filter(p=>stock(state,p.id).available<=p.reorderPoint).sort((a,b)=>stock(state,a.id).available-stock(state,b.id).available);
  const open=state.orders.filter(o=>['Draft','Confirmed'].includes(o.status));
  return `${!preview?head('YOUR STORE AT A GLANCE','Ready for another day at the market.','Keep drinks cold, grab-and-go food ready, and everyday favorites in stock.',btn(icon('plus')+' Add product','add-product')):''}<div class="metrics-grid">${metric('Inventory value',money(inventoryValue(state)),'Physical stock, at unit cost','box')}${metric('Active products',state.products.length,'Across '+state.settings.locations.length+' locations','inventory')}${metric('Low-stock products',low.length,'Available at or below reorder point','insights','amber')}${metric('Open orders',open.length,'Draft and confirmed sales orders','sales','blue')}</div><div class="charts-grid">${chart('sales',preview)}${chart('movement',preview)}</div><div class="overview-bottom"><section class="card"><div class="card-heading"><div><h2>Needs a little attention</h2><p>Shelf essentials running low</p></div><a href="#app/inventory" class="text-link">View inventory</a></div>${table(['Product','Available','Status'],low.slice(0,4).map(p=>`<tr><td>${productCell(p)}</td><td><b>${stock(state,p.id).available}</b></td><td>${badge(stockStatus(p))}</td></tr>`))}</section><section class="card"><div class="card-heading"><div><h2>Recent orders</h2><p>The latest customer requests</p></div><a href="#app/sales" class="text-link">View orders</a></div>${table(['Order / customer','Total','Status'],state.orders.slice(-4).reverse().map(o=>`<tr><td><a href="#app/sales/${o.id}" class="record-link">${o.number}</a><small>${e(contactName('customers',o.customerId))}</small></td><td>${money(orderTotal(o))}</td><td>${badge(o.status)}</td></tr>`))}</section></div>${!preview?`<div class="overview-bottom"><section class="card"><div class="card-heading"><div><h2>Quick actions</h2><p>A shorter path to your next task</p></div></div><div class="quick-actions">${btn(icon('plus')+' Add product','add-product','secondary')}${btn(icon('sales')+' Create order','create-sale','secondary')}${btn(icon('purchasing')+' Receive stock','go-purchasing','secondary')}</div></section><section class="card"><div class="card-heading"><h2>Recent activity</h2></div><div class="activity-list">${state.activity.slice(-4).reverse().map(a=>`<div><span class="activity-icon">${icon('check')}</span><span><b>${e(a.message)}</b><small>${fullDate(a.at)}</small></span></div>`).join('')||empty('No activity yet','Your changes will appear here.')}</div></section></div>`:''}`;
}
const openInventoryCategories=new Set();
function inventory(){
  if(detail)return productDetail(detail);
  const rows=state.products.filter(p=>(!filters.search||[p.name,p.sku].some(v=>v.toLowerCase().includes(filters.search.toLowerCase())))&&(!filters.category||p.category===filters.category)&&(!filters.supplier||p.supplierId===filters.supplier)&&(!filters.status||stockStatus(p,filters.location)===filters.status));
  rows.sort((a,b)=>filters.sort==='quantity'?stock(state,a.id,filters.location).available-stock(state,b.id,filters.location).available:filters.sort==='value'?stock(state,b.id,filters.location).onHand*b.costCents-stock(state,a.id,filters.location).onHand*a.costCents:a.name.localeCompare(b.name));
  const groups=[...new Set(rows.map(p=>p.category))].sort();
  const searching=filters.search||filters.category||filters.supplier||filters.status;
  const categoryCards=groups.map(category=>{
    const products=rows.filter(p=>p.category===category),low=products.filter(p=>stock(state,p.id,filters.location).available<=p.reorderPoint).length;
    return `<details class="inventory-category card" data-category="${e(category)}" ${searching||openInventoryCategories.has(category)?'open':''}><summary><span class="category-icon">${icon('inventory')}</span><span class="category-title"><b>${e(category)}</b><small>${products.length} ${products.length===1?'product':'products'}${filters.location?' at '+e(lname(filters.location)):''}</small></span>${low?'<span class="category-warning">'+low+' low</span>':'<span class="category-ready">Stock ready</span>'}<span class="category-chevron" aria-hidden="true">&#8964;</span></summary><div class="category-products">${products.map(p=>{const v=stock(state,p.id,filters.location);const locations=state.settings.locations.filter(l=>!filters.location||l.id===filters.location);return `<article class="category-product"><div class="category-product-top">${productCell(p)}<span class="category-product-count"><b>${v.available}</b><small>ready to sell</small></span></div><div class="category-product-source">From ${e(p.supplierId?contactName('suppliers',p.supplierId):'No supplier assigned')}</div><div class="category-product-locations">${locations.map(l=>'<span>'+e(l.name)+': <b>'+stock(state,p.id,l.id).available+'</b> ready</span>').join('')}</div><div class="category-product-footer">${badge(stockStatus(p,filters.location))}<a class="text-link" href="#app/inventory/${p.id}">View stock &amp; history</a></div></article>`;}).join('')}</div></details>`;
  }).join('');
  return head('PRODUCTS & STOCK','Inventory','Choose a category to see its products, suppliers, and store locations.',btn('Import CSV','import','secondary')+btn('Export CSV','export','secondary')+btn(icon('plus')+' Add product','add-product'))+`<section class="card inventory-browse-tools"><div class="filter-bar"><label class="search-input">${icon('search')}<input data-filter="search" aria-label="Search products" placeholder="Find a product or SKU" value="${e(filters.search||'')}"/></label>${select('location','Location',state.settings.locations,filters.location,'All locations')}${select('status','Stock status',['In stock','Low stock','Out of stock'],filters.status,'All stock levels')}</div><details class="inventory-extra-filters" ${filters.category||filters.supplier||filters.sort?'open':''}><summary>More filters &amp; sorting</summary><div>${select('category','Category',[...new Set(state.products.map(p=>p.category))],filters.category,'All categories')}${select('supplier','Supplier',state.suppliers,filters.supplier,'All suppliers')}${select('sort','Sort inventory',[{value:'name',label:'Name A-Z'},{value:'quantity',label:'Lowest available'},{value:'value',label:'Highest stock value'}],filters.sort||'name',null)}</div></details></section><div class="inventory-browse-caption"><span>${rows.length} products in ${groups.length} categories</span><span>Open a category to browse</span></div><div class="inventory-category-grid">${categoryCards||empty('No matching products','Try another search or filter, or add your first product.')}</div><p class="inventory-browse-note">Ready to sell = physical stock minus units reserved for pickups. Open a product for costs, counts, and movement history.</p>`;
}
function productDetail(id){
  const p=state.products.find(p=>p.id===id);if(!p)return empty('Product not found','Return to Inventory to choose a product.');const v=stock(state,id);
  return `<a class="back-link" href="#app/inventory">← Inventory</a>`+head(e(p.sku),e(p.name),`${e(p.category)} · ${e(p.supplierId?contactName('suppliers',p.supplierId):'No supplier assigned')}`,btn('Adjust stock','adjust','secondary',`data-id="${id}"`)+btn('Edit product','edit-product','primary',`data-id="${id}"`))+`<div class="metrics-grid">${metric('On hand',v.onHand,'Physical units currently held')}${metric('Reserved',v.reserved,'Committed to confirmed orders')}${metric('Available',v.available,'Ready for a new order')}${metric('Incoming',v.incoming,'Outstanding purchase quantities')}</div><section class="card"><div class="card-heading"><div><h2>Stock by location</h2><p>Unit cost ${money(p.costCents)} · selling price ${money(p.priceCents)} · reorder point ${p.reorderPoint}</p></div></div>${table(['Location','On hand','Reserved','Available','Incoming'],state.settings.locations.map(l=>{const v=stock(state,id,l.id);return `<tr><td>${e(l.name)}</td><td>${v.onHand}</td><td>${v.reserved}</td><td>${v.available}</td><td>${v.incoming}</td></tr>`;}))}</section><section class="card spaced"><div class="card-heading"><h2>Movement history</h2></div>${movementTable(state.movements.filter(m=>m.productId===id))}</section>`;
}
function movementTable(movements){return table(['Date','Product / location','Stock change','Reserved change','On hand after','Reason / order'],[...movements].reverse().map(m=>`<tr><td>${fullDate(m.at)}</td><td><b>${e(pname(m.productId))}</b><small>${e(lname(m.locationId))}</small></td><td class="${m.delta>0?'positive':m.delta<0?'negative':''}">${m.delta>0?'+':''}${m.delta}</td><td>${m.reservedDelta>0?'+':''}${m.reservedDelta}</td><td>${m.after}</td><td>${e(m.reason)}${m.related?`<small>${e(m.related)}</small>`:''}</td></tr>`));}
function orders(purchase=false){
  const collection=purchase?state.purchases:state.orders;
  if(detail){const o=collection.find(o=>o.id===detail);if(!o)return empty('Order not found','Return to the order list.');return orderDetail(o,purchase);}
  const visible=collection.filter(o=>(!filters.search||[o.number,contactName(purchase?'suppliers':'customers',purchase?o.supplierId:o.customerId)].some(v=>v.toLowerCase().includes(filters.search.toLowerCase())))&&(!filters.status||o.status===filters.status)).slice().reverse();
  return head(purchase?'SUPPLIER ORDERS':'COUNTER SALES & PICKUP',purchase?'Purchasing':'Sales orders',purchase?'Track grocery deliveries and receive cases or units as they arrive.':'Track counter sales and lunch pickups. Confirm to reserve; fulfill to record the sale.',btn(icon('plus')+(purchase?' Create purchase order':' Create order'),purchase?'create-purchase':'create-sale'))+`<section class="card"><div class="filter-bar"><label class="search-input">${icon('search')}<input data-filter="search" aria-label="Search orders" placeholder="Search order or ${purchase?'supplier':'customer'}" value="${e(filters.search||'')}"/></label>${select('status','Order status',purchase?['Open','Partially received','Received']:['Draft','Confirmed','Fulfilled','Cancelled'],filters.status,'All statuses')}</div>${table(['Order',purchase?'Supplier':'Customer','Location',purchase?'Expected':'Created',purchase?'Received / ordered':'Total','Status','Action'],visible.map(o=>`<tr><td><a class="record-link" href="#app/${purchase?'purchasing':'sales'}/${o.id}">${o.number}</a></td><td>${e(contactName(purchase?'suppliers':'customers',purchase?o.supplierId:o.customerId))}</td><td>${e(lname(o.locationId))}</td><td>${purchase?e(o.expected):date(o.at)}</td><td>${purchase?o.lines.reduce((n,l)=>n+l.received,0)+' / '+o.lines.reduce((n,l)=>n+l.quantity,0)+' units':money(orderTotal(o))}</td><td>${badge(o.status)}</td><td><a class="text-link" href="#app/${purchase?'purchasing':'sales'}/${o.id}">View order</a></td></tr>`))}<div class="card-footer">${visible.length} orders <span>${purchase?'Incoming = ordered − received':'Confirm reserves stock. Fulfill deducts it.'}</span></div></section>`;
}
function orderDetail(o,purchase){
  let actions='';if(purchase&&['Open','Partially received'].includes(o.status))actions=btn('Receive stock','receive','primary',`data-id="${o.id}"`);if(!purchase){if(o.status==='Draft')actions+=btn('Confirm order','sales-status','primary',`data-id="${o.id}" data-status="Confirmed"`);if(o.status==='Confirmed')actions+=btn('Fulfill order','sales-status','primary',`data-id="${o.id}" data-status="Fulfilled"`);if(['Draft','Confirmed'].includes(o.status))actions+=btn('Cancel order','cancel-sale','danger',`data-id="${o.id}"`);}
  return `<a class="back-link" href="#app/${purchase?'purchasing':'sales'}">← ${purchase?'Purchasing':'Sales orders'}</a>`+head(purchase?'PURCHASE ORDER':'SALES ORDER',o.number,`${e(contactName(purchase?'suppliers':'customers',purchase?o.supplierId:o.customerId))} · ${e(lname(o.locationId))}`,actions)+`<section class="card"><div class="card-heading">${badge(o.status)}<p>${purchase?'Expected '+e(o.expected):'Created '+fullDate(o.at)}</p></div>${table(['Product',purchase?'Ordered':'Quantity',...(purchase?['Received','Outstanding']:['Available now']),'Unit price','Line total'],o.lines.map(l=>`<tr><td>${productCell(state.products.find(p=>p.id===l.productId))}</td><td>${l.quantity}</td>${purchase?`<td>${l.received}</td><td>${l.quantity-l.received}</td>`:`<td>${stock(state,l.productId,o.locationId).available}</td>`}<td>${money(l.priceCents)}</td><td>${money(l.priceCents*l.quantity)}</td></tr>`))}<div class="order-total"><span>${purchase?'Purchase':'Order'} total <small>Before tax or shipping</small></span><strong>${money(orderTotal(o))}</strong></div></section>${purchase?`<section class="card spaced"><div class="card-heading"><h2>Delivery receipts</h2></div>${table(['Reference','Received at','Units'],o.receipts.map(r=>`<tr><td>${e(r.reference)}</td><td>${fullDate(r.at)}</td><td>${r.lines.reduce((n,l)=>n+l.quantity,0)}</td></tr>`))}</section>`:''}<section class="card spaced"><div class="card-heading"><h2>Related movements</h2></div>${movementTable(state.movements.filter(m=>m.related===o.number))}</section>`;
}
function contacts(kind){const collection=state[kind],singular=kind==='customers'?'customer':'supplier';if(detail){const c=collection.find(c=>c.id===detail);if(!c)return empty('Contact not found','Choose another contact.');const related=(kind==='customers'?state.orders:state.purchases).filter(o=>(kind==='customers'?o.customerId:o.supplierId)===c.id);return `<a class="back-link" href="#app/${kind}">← ${kind==='customers'?'Customers':'Suppliers'}</a>`+head('CONTACT DETAILS',e(c.name),e(c.email||'No email added'),btn('Edit contact','edit-contact','primary',`data-id="${c.id}" data-kind="${singular}"`))+`<section class="card contact-details"><p><b>Phone</b> ${e(c.phone||'Not provided')}</p><p><b>Address / notes</b> ${e(c.address||'Not provided')}</p></section><section class="card spaced"><div class="card-heading"><h2>Related ${kind==='customers'?'sales':'purchase'} orders</h2></div>${table(['Order','Total','Status'],related.map(o=>`<tr><td><a class="record-link" href="#app/${kind==='customers'?'sales':'purchasing'}/${o.id}">${o.number}</a></td><td>${money(orderTotal(o))}</td><td>${badge(o.status)}</td></tr>`))}</section>`;}
  const visible=collection.filter(c=>!filters.search||[c.name,c.email,c.phone].some(v=>v.toLowerCase().includes(filters.search.toLowerCase())));return head('YOUR STORE CONNECTIONS',kind==='customers'?'Customers':'Suppliers','Keep contact details and related orders together.',btn(icon('plus')+' Add '+singular,'add-contact','primary',`data-kind="${singular}"`))+`<section class="card"><div class="filter-bar"><label class="search-input">${icon('search')}<input data-filter="search" aria-label="Search contacts" placeholder="Search name, email, or phone" value="${e(filters.search||'')}"/></label></div>${table(['Name','Email','Phone','Orders','Action'],visible.map(c=>`<tr><td><a class="record-link" href="#app/${kind}/${c.id}">${e(c.name)}</a></td><td>${e(c.email||'—')}</td><td>${e(c.phone||'—')}</td><td>${(kind==='customers'?state.orders:state.purchases).filter(o=>(kind==='customers'?o.customerId:o.supplierId)===c.id).length}</td><td>${btn('Edit','edit-contact','small secondary',`data-id="${c.id}" data-kind="${singular}"`)}</td></tr>`))}</section>`;
}
function insightsPage(){return simpleInsights(state,insights(state),{money,icon});}
function settings(){return head('MAKE IT YOURS','Settings','Store preferences for Bargetown Market and your stock locations.')+`<section class="card settings-card"><form id="settingsForm"><h2>Business preferences</h2><div class="form-grid">${field('name','Business name',state.settings.name)}<label>Currency<select name="currency">${['USD','EUR','GBP','CAD','AUD'].map(c=>option(c,c,state.settings.currency)).join('')}</select></label>${field('defaultReorder','Default reorder point',state.settings.defaultReorder,'number','min="0" step="1"')}</div><p class="form-help">Currency controls the display of all amounts; it does not convert existing prices. The reorder default applies to new products.</p><h3>Locations</h3><div id="settingsLocations">${state.settings.locations.map(l=>`<label class="location-field">Location name<input name="location" data-id="${l.id}" value="${e(l.name)}" required maxlength="100"/></label>`).join('')}</div>${btn(icon('plus')+' Add location','add-location','secondary','type="button"')}<div class="form-footer"><button class="button primary">Save settings</button></div><p class="form-error" id="settingsError" role="alert"></p></form></section><div class="overview-bottom spaced"><section class="card explanation"><span class="badge blue">Working demo capabilities</span><h2>Saved on this device</h2><p>Products, contacts, orders, locations, and movements are saved in this browser. Refreshing keeps your changes. Export a backup before clearing browser data.</p>${btn('Download demo backup','backup','secondary')}</section><section class="card explanation"><span class="badge">Future capabilities · unavailable</span><h2>Production connections</h2><p>Shared databases, team accounts, automated POS payments, accounting, shipping, and ecommerce integrations are not connected in this demo.</p><p>A production release needs secure sign-in, server-side transactions, backups, and verified integration events.</p></section></div><section class="card reset-card spaced"><div><h2>Reset demo data</h2><p>Replace this browser’s workspace with the original sample business. Your changes will be removed.</p></div>${btn('Reset demo data','reset','danger')}</section>`;}
function landing(){return `<div class="landing" id="main" tabindex="-1"><header class="marketing-nav"><a href="#" class="logo">${icon('inventory')}<span>stock<span class="logo-light">sense</span></span></a><nav aria-label="Public navigation"><a href="#how-it-works">How it works</a><a href="#built-for">Who it’s for</a><a href="#faq">FAQs</a></nav><a href="#app/overview" class="button light">Explore the demo ${icon('arrow')}</a></header><section class="hero"><div class="hero-copy"><span class="hero-label"><span></span> Stock Sense for Bargetown Market</span><h1>Less inventory guesswork.<br><em>More room to grow.</em></h1><p>Know what’s in stock. Keep orders moving. Restock with confidence. One straightforward workspace for the everyday business of running your business.</p><div class="hero-actions"><a class="button primary" href="#app/overview">Explore the demo ${icon('arrow')}</a><a class="button ghost" href="#how-it-works">See how it works</a></div><div class="hero-footnote">Browser-based demo <span>·</span> No signup or payment required</div></div><div class="preview-wrap"><div class="floating-callout callout-one">${icon('check')}<div><b>From cooler to back stockroom</b><small>Every store item in one place</small></div></div><div class="product-preview"><aside><div class="preview-logo">${icon('inventory')} stock sense</div>${['overview','inventory','sales','purchasing','insights'].map((p,i)=>`<a href="#app/${p}" class="${i===0?'selected':''}">${icon(p)} ${p==='sales'?'Sales orders':p[0].toUpperCase()+p.slice(1)}</a>`).join('')}<span class="preview-demo">DEMO WORKSPACE</span></aside><div class="preview-content"><div class="preview-top"><span>${e(state.settings.name)}</span><span class="avatar">SS</span></div><div class="preview-body"><div class="preview-page-title"><div><small>YOUR STORE AT A GLANCE</small><h3>Overview</h3></div><a href="#app/inventory" data-action="add-product" class="button primary small">+ Add product</a></div>${overview(true)}</div></div></div><div class="floating-callout callout-two"><span class="callout-icon">${icon('insights')}</span><div><b>Stay one step ahead</b><small>Clear, practical restock suggestions</small></div></div></div></section><section class="landing-promise"><span>LESS SPREADSHEET. MORE HEADSPACE.</span><h2>Your shelves, daily sales, and deliveries.<br>Finally on the same page.</h2><p>One everyday workspace for Bargetown Market: grab-and-go lunches, cold drinks, snacks, groceries, and the next supplier delivery.</p></section><section id="how-it-works" class="how-section"><div class="section-intro"><span class="eyebrow">A SIMPLE WAY TO STAY ON TOP OF THINGS</span><h2>From shelf to sale,<br>without the scramble.</h2></div><div class="feature-grid"><article><span class="feature-number">01</span>${icon('inventory')}<h3>Know what you have</h3><p>Find products quickly. See physical stock, reserved units, and what is available at each location.</p><a href="#app/inventory">Explore inventory ${icon('arrow')}</a></article><article><span class="feature-number">02</span>${icon('sales')}<h3>Keep the counter moving</h3><p>Record a counter sale or reserve a lunch pickup. Fulfill it to update stock, then see what is selling through the day.</p><a href="#app/sales">Explore orders ${icon('arrow')}</a></article><article><span class="feature-number">03</span>${icon('insights')}<h3>Restock with a reason</h3><p>See what is selling and what is sitting. Understand every recommendation with transparent calculations.</p><a href="#app/insights">Explore insights ${icon('arrow')}</a></article></div></section><section id="built-for" class="audience-section"><div class="section-intro"><span class="eyebrow">BUILT AROUND BARGETOWN MARKET</span><h2>Big on useful.<br>Small on complexity.</h2><p>Built around a neighborhood convenience store: quick stops, lunch pickups, and shelves that need to stay ready.</p></div><div class="audience-grid"><article>${icon('suppliers')}<h3>Drinks & everyday groceries</h3><p>Keep water, soda, milk, bread, and everyday essentials easy to find. See what is on the sales floor and what is in back stock.</p></article><article>${icon('purchasing')}<h3>Fresh food & lunch pickups</h3><p>Track sandwiches, wraps, and fruit cups. Reserve pickup orders and review slow-moving fresh food before ordering more.</p></article><article>${icon('settings')}<h3>Snacks & supplier deliveries</h3><p>Keep popular snacks stocked, record each delivery, and use recent sales to decide what needs another case.</p></article></div></section><section class="faq-section" id="faq"><div><span class="eyebrow">GOOD QUESTIONS</span><h2>A few things<br>worth knowing.</h2></div><div>${[['Can I try it without an account?','Yes. Explore the full demo without signup. The sample workspace and your edits are stored in your browser.'],['Can I track more than one location?','Yes. Stock is tracked by product and location. Orders reserve and fulfill from the location you choose.'],['How are restock suggestions calculated?','Suggestions use reorder points and, when there is enough recorded history, recent fulfilled sales. Every estimate explains its time period and rules.'],['Is this connected to my checkout or accounting system?','No. This demo has no connected payment, ecommerce, shipping, or accounting integrations. Those need a secure production backend and a provider-specific connection.'],['Can my team use the same inventory?','This browser demo is for exploring workflows. Shared team inventory needs a database, secure accounts, and server-side stock updates.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="landing-cta"><span>MAKE A LITTLE ROOM FOR CLARITY.</span><h2>Keep the neighborhood?s favorites ready.</h2><a class="button primary" href="#app/overview">Explore Stock Sense ${icon('arrow')}</a></section><footer class="marketing-footer"><a href="#" class="logo">${icon('inventory')} stock sense</a><p>Know what’s in stock. Keep orders moving. Restock with confidence.</p><span>Stock Sense · Working browser demo</span></footer></div>`;}
const titles={overview:'Overview',inventory:'Inventory',sales:'Sales & Pickups',purchasing:'Purchasing',customers:'Customers',suppliers:'Suppliers',insights:'Insights',settings:'Settings'};
function shell(content){return `<div class="workspace"><aside class="sidebar" id="sidebar"><a class="logo" href="#">${icon('inventory')}<span>stock<span class="logo-light">sense</span></span></a><div class="business-switch"><span class="business-monogram">${e(state.settings.name.split(' ').slice(0,2).map(w=>w[0]).join(''))}</span><div><b>${e(state.settings.name)}</b><small>Demo workspace</small></div></div><p class="nav-label">WORKSPACE</p><nav aria-label="Application pages">${Object.entries(titles).map(([key,title])=>`<a href="#app/${key}" ${page===key?'class="active" aria-current="page"':''}>${icon(key)}<span>${title}</span></a>`).join('')}</nav><div class="sidebar-bottom"><span class="badge sidebar-badge">Browser demo</span><p>Your changes stay on this device.</p><a href="#">Back to Stock Sense</a></div></aside><div class="workspace-main"><header class="workspace-topbar">${btn(icon('menu'),'menu','icon-button','aria-label="Toggle navigation" aria-expanded="false"')}<div><span class="breadcrumb">Workspace <span>/</span> ${titles[page]||'Overview'}</span></div><div class="topbar-right"><span class="demo-label">Sample business · browser storage</span><span class="avatar">SS</span></div></header><main id="main" tabindex="-1">${storageError?`<div class="error-banner" role="alert">${e(storageError)} Changes are disabled until storage works or you reset the demo in Settings.</div>`:''}${content}</main><footer class="workspace-footer">Stock Sense demo <span>On hand = physical stock · Reserved = committed · Available = on hand − reserved</span></footer></div></div>`;}
function render(){const hash=location.hash;const parts=hash.replace(/^#app\/?/,'').split('/');const app=hash.startsWith('#app');page=titles[parts[0]]?parts[0]:'overview';detail=parts[1]||'';document.title=app?`${titles[page]} · Stock Sense`:'Stock Sense · Less inventory guesswork';$('#root').innerHTML=app?shell(({overview:()=>overview(),inventory,sales:()=>orders(),purchasing:()=>orders(true),customers:()=>contacts('customers'),suppliers:()=>contacts('suppliers'),insights:insightsPage,settings}[page])()):landing();if(!app&&/^#[a-z-]+$/.test(hash)&&$(hash))$(hash).scrollIntoView({behavior:'smooth'});}
document.addEventListener('toggle',event=>{const target=event.target;if(!target.matches?.('.inventory-category')||filters.search||filters.category||filters.supplier||filters.status)return;if(target.open)openInventoryCategories.add(target.dataset.category);else openInventoryCategories.delete(target.dataset.category);},true);
window.addEventListener('hashchange',()=>{filters={};render();if(location.hash.startsWith('#app'))window.scrollTo(0,0);});
window.addEventListener('storage',event=>{if(event.key===KEY){try{state=load(localStorage);storageError='';render();}catch(error){toast(error.message,true);}}});
function field(name,label,value='',type='text',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${attrs} required ${type==='text'?'maxlength="150"':''}/></label>`;}
function picker(name,label,items,value='',none=false){return `<label>${label}<select name="${name}" ${none?'':'required'}>${none?option('','No supplier',value):option('','Choose '+label.toLowerCase(),value)}${items.map(item=>option(item.id,item.name,value)).join('')}</select></label>`;}
function openModal(type,id='',kind=''){
  modalType=type;modalId=id;modalToken=uid();csvRows=[];importRows=[];let title='',body='',submit='Save';
  if(type==='product'){const p=state.products.find(p=>p.id===id);title=p?'Edit product':'Add product';body=`<div class="form-grid">${field('name','Product name',p?.name)}${field('sku','SKU',p?.sku)}${field('category','Category',p?.category||'General')}${picker('supplierId','Supplier',state.suppliers,p?.supplierId,true)}${field('cost','Unit cost',((p?.costCents||0)/100).toFixed(2),'text','inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?"')}${field('price','Selling price',((p?.priceCents||0)/100).toFixed(2),'text','inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?"')}${field('reorderPoint','Reorder point',p?.reorderPoint??state.settings.defaultReorder,'number','min="0" step="1"')}${!p?field('quantity','Opening on-hand quantity',0,'number','min="0" step="1"')+picker('locationId','Opening stock location',state.settings.locations,state.settings.locations[0].id):''}</div><p class="form-help">Counts are whole units. Adjust existing stock through a dated stock adjustment.</p>`;}
  if(type==='adjust'){title='Adjust stock';body=`<p>Record a physical stock count for ${e(pname(id))}. A reason is required for the movement history.</p><div class="form-grid">${picker('locationId','Location',state.settings.locations,state.settings.locations[0].id)}${field('quantity','New on-hand quantity',stock(state,id,state.settings.locations[0].id).onHand,'number','min="0" step="1"')}${field('reason','Reason (damage, count correction, etc.)','','text','')}</div><p id="adjustAvailable" class="form-help">${stock(state,id,state.settings.locations[0].id).reserved} units reserved at this location.</p>`;submit='Save adjustment';}
  if(type==='sale'||type==='purchase'){const purchase=type==='purchase';title=purchase?'Create purchase order':'Create sales order';submit=purchase?'Create purchase order':'Save draft order';body=`<div class="form-grid">${picker(purchase?'supplierId':'customerId',purchase?'Supplier':'Customer',state[purchase?'suppliers':'customers'])}${picker('locationId',purchase?'Receiving location':'Fulfillment location',state.settings.locations,state.settings.locations[0].id)}${purchase?field('expected','Expected delivery',new Date(Date.now()+7*86400000).toISOString().slice(0,10),'date'):''}</div><div class="line-heading"><h3>Products</h3>${btn('+ Add line','add-line','small secondary','type="button"')}</div><div id="orderLines">${lineForm(purchase)}</div><div class="form-total">Estimated total <strong id="formTotal">${money(0)}</strong></div><p class="form-help">${purchase?'Stock is added only when you receive a delivery.':'Drafts do not reserve stock. Confirm the order when you are ready.'} Prices exclude tax and shipping.</p>`;}
  if(type==='receive'){const o=state.purchases.find(o=>o.id===id);title='Receive stock · '+o.number;submit='Record receipt';body=`<p>Receiving at <b>${e(lname(o.locationId))}</b>. Enter only what arrived in this delivery.</p>${field('reference','Delivery / packing slip reference')}<p class="form-help">Use a unique reference from this delivery. Reusing it is blocked to prevent duplicate receiving.</p><div class="receive-lines">${o.lines.filter(l=>l.received<l.quantity).map(l=>`<label>${e(pname(l.productId))}<small>${l.received} received · ${l.quantity-l.received} outstanding</small><input type="number" name="receive" data-product="${l.productId}" min="0" max="${l.quantity-l.received}" step="1" value="0" required/></label>`).join('')}</div>`;}
  if(type==='contact'){modalId=JSON.stringify({id,kind});const c=state[kind==='supplier'?'suppliers':'customers'].find(c=>c.id===id);title=(id?'Edit ':'Add ')+kind;body=`<div class="form-grid">${field('name','Name',c?.name)}<label>Email<input name="email" type="email" value="${e(c?.email||'')}" maxlength="150"/></label><label>Phone<input name="phone" type="tel" value="${e(c?.phone||'')}" maxlength="100"/></label><label class="full-width">Address / notes<textarea name="address" maxlength="500">${e(c?.address||'')}</textarea></label></div>`;}
  if(type==='import'){title='Import inventory CSV';submit='Confirm and import';body=`<p>Review your file before saving. Matching SKUs update product details and the physical count at the chosen location. Other locations remain unchanged.</p><div class="form-grid">${picker('locationId','Import location',state.settings.locations,state.settings.locations[0].id)}<label>CSV file<input id="csvFile" type="file" accept=".csv,text/csv" required/></label></div><p class="form-help">Required: SKU, name, quantity. Optional: location, category, unitCost, sellingPrice, reorderPoint. A mapped location overrides the selected default and must match a location in Settings.</p>${btn('Download CSV template','template','small secondary','type="button"')}<div id="importMapping"></div><div id="importPreview"></div>`;}
  if(type==='cancel'){title='Cancel this order?';submit='Cancel order';body='<p>Any reservation for this order will be released. Physical on-hand stock will stay the same.</p>';}
  if(type==='reset'){title='Reset the demo workspace?';submit='Reset demo data';body='<p>This replaces all products, contacts, orders, and stock history in this browser with the original sample business. Download a backup in Settings first if you want to keep your records.</p>';}
  $('#modalContent').innerHTML=`<form id="modalForm"><div class="modal-heading"><div><span class="eyebrow">STOCK SENSE</span><h2 id="modalTitle">${title}</h2></div><button type="button" class="close-button" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}<p class="form-error" id="modalError" role="alert"></p></div><div class="modal-footer">${btn('Cancel','close-modal','secondary','type="button"')}<button class="button ${type==='reset'||type==='cancel'?'danger':'primary'}" type="submit" id="modalSubmit" ${type==='import'?'disabled':''}>${submit}</button></div></form>`;
  $('#modal').showModal();$('#modal').querySelector('input,select,textarea')?.focus();
}
function lineForm(purchase=false){return `<div class="order-line"><label>Product<select name="lineProduct" required>${option('','Choose a product','')}${state.products.map(p=>option(p.id,p.name+' · '+p.sku,'')).join('')}</select></label><label>Quantity<input name="lineQuantity" type="number" value="1" min="1" step="1" required/></label><label>Unit ${purchase?'cost':'price'}<input name="linePrice" type="text" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" value="0.00" required/></label><button type="button" class="remove-line" data-action="remove-line" aria-label="Remove product line">×</button></div>`;}
async function transact(type,data,token=uid()){if(storageError)throw Error('Browser storage is unavailable. Resolve storage or reset before changing records.');state=await commit(localStorage,{type,data,token});render();}
function exportFile(content,name,type='text/csv'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const csvCell=s=>'"'+String(s).replaceAll('"','""')+'"';
function exportInventory(){const header=['sku','name','category','location','quantity','reserved','available','reorderPoint','unitCost','sellingPrice','supplier'];const rows=state.products.flatMap(p=>state.settings.locations.map(l=>{const v=stock(state,p.id,l.id);return [p.sku,p.name,p.category,l.name,v.onHand,v.reserved,v.available,p.reorderPoint,(p.costCents/100).toFixed(2),(p.priceCents/100).toFixed(2),contactName('suppliers',p.supplierId)];}));exportFile([header,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n'),'stock-sense-inventory.csv');}
function updateTotal(){let total=0;try{for(const row of $('#orderLines')?.children||[])total+=Number(row.querySelector('[name=lineQuantity]').value)*cents(row.querySelector('[name=linePrice]').value);}catch{}if($('#formTotal'))$('#formTotal').textContent=money(total);}
function previewImport(){
  const fields=['sku','name','quantity','location','category','unitCost','sellingPrice','reorderPoint'];const mapping=Object.fromEntries([...$('#importMapping').querySelectorAll('select')].map(x=>[x.name,x.value]));const errors=[];importRows=[];
  for(const [i,row] of csvRows.slice(1).entries()){
    const record={};for(const name of fields)if(mapping[name]!=='')record[name]=row[Number(mapping[name])];
    try{if(!record.sku?.trim()||!record.name?.trim())throw Error('SKU and name are required.');if(record.quantity===undefined||record.quantity.trim()===''||!/^\d+$/.test(record.quantity.trim()))throw Error('Quantity must be a nonnegative whole number.');if(record.reorderPoint?.trim()==='')delete record.reorderPoint;
      const existing=state.products.find(p=>p.sku.toLowerCase()===record.sku.trim().toLowerCase());if(record.unitCost===undefined)record.unitCost=((existing?.costCents||0)/100).toFixed(2);if(record.sellingPrice===undefined)record.sellingPrice=((existing?.priceCents||0)/100).toFixed(2);
      const rowTrial=apply(state,{type:'import',data:{locationId:$('#modalForm [name=locationId]').value,rows:[record]}});void rowTrial;importRows.push(record);
    }catch(error){errors.push(`Row ${i+2}: ${error.message}`);}
  }
  if(!errors.length)try{apply(state,{type:'import',data:{locationId:$('#modalForm [name=locationId]').value,rows:importRows}});}catch(error){errors.push(error.message);}
  $('#importPreview').innerHTML=`<h3>Preview · ${importRows.length} valid of ${csvRows.length-1} rows</h3>${errors.length?`<div class="error-banner">${errors.map(error=>`<p>${e(error)}</p>`).join('')}</div>`:'<div class="success-banner">All rows are valid. Review the first 10 products below before confirming.</div>'}${table(['SKU','Product','Location','New on hand','Unit cost','Price'],importRows.slice(0,10).map(r=>`<tr><td>${e(r.sku)}</td><td>${e(r.name)}</td><td>${e(r.location||lname($('#modalForm [name=locationId]').value))}</td><td>${e(r.quantity)}</td><td>${e(r.unitCost||'0')}</td><td>${e(r.sellingPrice||'0')}</td></tr>`))}`;$('#modalSubmit').disabled=errors.length>0||!importRows.length;
}
document.addEventListener('input',event=>{
  const target=event.target;if(target.dataset.filter){const start=target.selectionStart;filters[target.dataset.filter]=target.value;const key=target.dataset.filter;render();const input=$(`[data-filter="${key}"]`);input.focus();if(input.setSelectionRange&&start!==null)input.setSelectionRange(start,start);}
  if(target.closest('#orderLines'))updateTotal();
});
document.addEventListener('change',async event=>{
  const target=event.target;
  if(target.dataset.filter&&target.tagName==='SELECT'){filters[target.dataset.filter]=target.value;render();}
  if(target.name==='lineProduct'){const p=state.products.find(p=>p.id===target.value);target.closest('.order-line').querySelector('[name=linePrice]').value=((p?.[modalType==='purchase'?'costCents':'priceCents']||0)/100).toFixed(2);updateTotal();}
  if(modalType==='adjust'&&target.name==='locationId'){$('#modalForm [name=quantity]').value=stock(state,modalId,target.value).onHand;$('#adjustAvailable').textContent=stock(state,modalId,target.value).reserved+' units reserved at this location.';}
  if(target.id==='csvFile'){try{const file=target.files[0];if(!file)return;if(file.size>2000000)throw Error('Use a CSV smaller than 2 MB.');csvRows=parseCSV(await file.text());if(csvRows.length>5001)throw Error('Import no more than 5,000 products at a time.');const fields=['sku','name','quantity','location','category','unitCost','sellingPrice','reorderPoint'];$('#importMapping').innerHTML='<h3>Map your columns</h3><div class="form-grid">'+fields.map(name=>`<label>${name}${['sku','name','quantity'].includes(name)?' (required)':''}<select name="${name}">${option('','Not mapped','')}${csvRows[0].map((h,i)=>option(i,h,h.trim().toLowerCase()===name.toLowerCase()?i:'')).join('')}</select></label>`).join('')+'</div>';previewImport();$('#modalError').textContent='';}catch(error){$('#modalError').textContent=error.message;$('#modalSubmit').disabled=true;}}
  if(target.closest('#importMapping')||(modalType==='import'&&target.name==='locationId'&&csvRows.length))previewImport();
});
document.addEventListener('click',async event=>{
  if(event.target.closest('.skip-link')){event.preventDefault();$('#main')?.focus();$('#main')?.scrollIntoView();return;}
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  try{
    if(action==='menu'){const open=$('#sidebar').classList.toggle('mobile-open');button.setAttribute('aria-expanded',String(open));}
    if(action==='add-product')openModal('product');if(action==='edit-product')openModal('product',button.dataset.id);if(action==='adjust')openModal('adjust',button.dataset.id);
    if(action==='create-sale')openModal('sale');if(action==='create-purchase')openModal('purchase');if(action==='receive')openModal('receive',button.dataset.id);
    if(action==='go-purchasing')location.hash='#app/purchasing';
    if(action==='add-contact'||action==='edit-contact')openModal('contact',button.dataset.id||'',button.dataset.kind);
    if(action==='close-modal')$('#modal').close();
    if(action==='sales-status'){button.disabled=true;await transact('sales-status',{id:button.dataset.id,status:button.dataset.status});toast('Order '+button.dataset.status.toLowerCase()+'. Stock records updated.');}
    if(action==='cancel-sale')openModal('cancel',button.dataset.id);
    if(action==='add-line'){$('#orderLines').insertAdjacentHTML('beforeend',lineForm(modalType==='purchase'));}
    if(action==='remove-line'){button.closest('.order-line').remove();updateTotal();}
    if(action==='export')exportInventory();if(action==='import')openModal('import');
    if(action==='template')exportFile('sku,name,quantity,category,unitCost,sellingPrice,reorderPoint\r\nEX-001,Example product,10,General,5.00,12.00,4\r\n','stock-sense-template.csv');
    if(action==='add-location')$('#settingsLocations').insertAdjacentHTML('beforeend','<label class="location-field">New location name<input name="location" required maxlength="100"/></label>');
    if(action==='backup')exportFile(JSON.stringify(state,null,2),'stock-sense-backup.json','application/json');
    if(action==='reset')openModal('reset');
  }catch(error){toast(error.message,true);button.disabled=false;}
});
document.addEventListener('submit',async event=>{
  if(!['modalForm','settingsForm'].includes(event.target.id))return;event.preventDefault();const form=event.target,fields=Object.fromEntries(new FormData(form));const submit=form.querySelector('button[type=submit]')||form.querySelector('.form-footer button');if(submit)submit.disabled=true;
  try{
    if(form.id==='settingsForm'){await transact('settings',{...fields,locations:[...form.querySelectorAll('[name=location]')].map(input=>({id:input.dataset.id||'',name:input.value}))});toast('Settings saved.');return;}
    let type,data;
    if(modalType==='product'){type='product';data={...fields,id:modalId||undefined,costCents:cents(fields.cost),priceCents:cents(fields.price)};}
    if(modalType==='adjust'){type='adjust';data={...fields,productId:modalId};}
    if(modalType==='sale'||modalType==='purchase'){type=modalType==='sale'?'sales-create':'purchase-create';data={...fields,lines:[...$('#orderLines').children].map(row=>({productId:row.querySelector('[name=lineProduct]').value,quantity:Number(row.querySelector('[name=lineQuantity]').value),priceCents:cents(row.querySelector('[name=linePrice]').value)}))};}
    if(modalType==='receive'){type='receive';data={id:modalId,reference:fields.reference,lines:[...form.querySelectorAll('[name=receive]')].map(input=>({productId:input.dataset.product,quantity:Number(input.value)}))};}
    if(modalType==='contact'){type='contact';data={...fields,...JSON.parse(modalId)};}
    if(modalType==='cancel'){type='sales-status';data={id:modalId,status:'Cancelled'};}
    if(modalType==='import'){previewImport();if($('#modalSubmit').disabled)throw Error('Fix the import errors before saving.');type='import';data={rows:importRows,locationId:fields.locationId};}
    if(modalType==='reset'){const reset=()=>{state=seed();localStorage.setItem(KEY,JSON.stringify(state));storageError='';};if(navigator.locks)await navigator.locks.request('stocksense-v3',reset);else reset();render();}else await transact(type,data,modalToken);
    $('#modal').close();toast(modalType==='reset'?'Demo data reset.':'Saved. Stock Sense is up to date.');
  }catch(error){const node=form.querySelector('.form-error');if(node)node.textContent=error.message;else toast(error.message,true);}
  finally{if(submit)submit.disabled=false;}
});
render();
